import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    if events.empty:
        return {
            "user_sessions": pd.DataFrame(
                columns=[
                    "user_id",
                    "session_num",
                    "session_start",
                    "session_end",
                    "event_count",
                    "heartbeat_count",
                ]
            )
        }

    events = events.sort_values(["user_id", "event_ts", "event_id"], kind="mergesort")

    threshold = timedelta(minutes=30)

    out_rows = []

    for user_id, grp in events.groupby("user_id", sort=False):
        session_num = 0
        open_session = None  # dict: start, last_activity, event_count, heartbeat_count

        def finalize(sess):
            out_rows.append(
                {
                    "user_id": user_id,
                    "session_num": sess["session_num"],
                    "session_start": sess["start"],
                    "session_end": sess["last_activity"],
                    "event_count": sess["event_count"],
                    "heartbeat_count": sess["heartbeat_count"],
                }
            )

        for row in grp.itertuples(index=False):
            ts = row.event_ts
            etype = row.event_type

            if etype in ("view", "click", "logout"):
                needs_new = False
                if open_session is None:
                    needs_new = True
                else:
                    if (ts - open_session["last_activity"]) > threshold:
                        needs_new = True

                if needs_new:
                    if open_session is not None:
                        finalize(open_session)
                    session_num += 1
                    open_session = {
                        "session_num": session_num,
                        "start": ts,
                        "last_activity": ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    open_session["last_activity"] = ts
                    open_session["event_count"] += 1

                if etype == "logout":
                    finalize(open_session)
                    open_session = None

            else:  # heartbeat
                if open_session is not None and (ts - open_session["last_activity"]) <= threshold:
                    open_session["event_count"] += 1
                    open_session["heartbeat_count"] += 1
                # else dropped

        if open_session is not None:
            finalize(open_session)

    result = pd.DataFrame(
        out_rows,
        columns=[
            "user_id",
            "session_num",
            "session_start",
            "session_end",
            "event_count",
            "heartbeat_count",
        ],
    )

    return {"user_sessions": result}
